 "content": "def transform(grid):
    # Color structural line endpoints/branches in the 1-pixel pattern as 2.
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            # endpoint is a 1 with exactly one orthogonal 1-neighbor
            n = sum(0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 1
                    for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
            if n == 1:
                out[r][c] = 2
    return out
